import type {
  AccessTokenProvider,
  ClientOptions,
  ListResponse,
  MeteredRequestOptions,
  OpenAIErrorBody,
  RequestOptions,
  ResponseObject,
} from "./types";

const IDEMPOTENCY_HEADER = "idempotency-key";
const MAX_COST_HEADER = "x-notorganic-max-cost-microusd";

export class NotOrganicError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly type: string,
    public readonly code: string | null,
    public readonly param: string | null,
  ) {
    super(message);
  }
}

export function generateIdempotencyKey(): string {
  if (typeof crypto.randomUUID === "function") {
    return `idem_${crypto.randomUUID()}`;
  }
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  bytes[6] = ((bytes[6] ?? 0) & 0x0f) | 0x40;
  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80;
  const hex = [...bytes].map((byte) => byte.toString(16).padStart(2, "0"));
  return `idem_${hex.slice(0, 4).join("")}-${hex
    .slice(4, 6)
    .join("")}-${hex.slice(6, 8).join("")}-${hex
    .slice(8, 10)
    .join("")}-${hex.slice(10).join("")}`;
}

async function resolveToken(provider: AccessTokenProvider): Promise<string> {
  const token = typeof provider === "function" ? await provider() : provider;
  if (!token) throw new Error("The access token provider returned an empty token.");
  return token;
}

async function throwResponseError(response: Response): Promise<never> {
  let body: OpenAIErrorBody | undefined;
  try {
    body = (await response.json()) as OpenAIErrorBody;
  } catch {
    // Preserve a useful HTTP error when a proxy returns a non-JSON body.
  }
  throw new NotOrganicError(
    body?.error?.message ?? `Gateway request failed with HTTP ${response.status}.`,
    response.status,
    body?.error?.type ?? "http_error",
    body?.error?.code ?? null,
    body?.error?.param ?? null,
  );
}

async function* parseSse<T>(response: Response): AsyncGenerator<T> {
  if (!response.body) return;
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += value;
      const events = buffer.split(/\r?\n\r?\n/);
      buffer = events.pop() ?? "";
      for (const event of events) {
        for (const line of event.split(/\r?\n/)) {
          if (!line.startsWith("data:")) continue;
          const data = line.slice(5).trim();
          if (data === "[DONE]") return;
          yield JSON.parse(data) as T;
        }
      }
    }
  } finally {
    reader.releaseLock();
  }
}

export class BaseClient {
  private readonly fetcher: NonNullable<ClientOptions["fetch"]>;
  private readonly baseURL: string;

  readonly responses = {
    create: <T extends ResponseObject = ResponseObject>(
      body: Record<string, unknown>,
      options?: MeteredRequestOptions,
    ) => this.meteredJson<T>("/v1/responses", body, options),
    retrieve: <T extends ResponseObject = ResponseObject>(
      responseId: string,
      options?: RequestOptions,
    ) =>
      this.json<T>(
        "GET",
        `/v1/responses/${encodeURIComponent(responseId)}`,
        undefined,
        options,
      ),
    get: <T extends ResponseObject = ResponseObject>(
      responseId: string,
      options?: RequestOptions,
    ) =>
      this.json<T>(
        "GET",
        `/v1/responses/${encodeURIComponent(responseId)}`,
        undefined,
        options,
      ),
    delete: (
      responseId: string,
      options?: RequestOptions,
    ) =>
      this.json<{ id: string; object: "response.deleted"; deleted: true }>(
        "DELETE",
        `/v1/responses/${encodeURIComponent(responseId)}`,
        undefined,
        options,
      ),
    inputItems: <T = unknown>(
      responseId: string,
      query: { after?: string; limit?: number } = {},
      options?: RequestOptions,
    ) =>
      this.json<ListResponse<T>>(
        "GET",
        this.withQuery(
          `/v1/responses/${encodeURIComponent(responseId)}/input_items`,
          query,
        ),
        undefined,
        options,
      ),
  };

  readonly chat = {
    completions: {
      create: async <T = unknown>(
        body: Record<string, unknown>,
        options?: MeteredRequestOptions,
      ): Promise<T | AsyncIterable<T>> => {
        const response = await this.metered(
          "/v1/chat/completions",
          body,
          options,
        );
        return body.stream === true
          ? parseSse<T>(response)
          : ((await response.json()) as T);
      },
    },
  };

  readonly embeddings = {
    create: <T = unknown>(
      body: Record<string, unknown>,
      options?: MeteredRequestOptions,
    ) => this.meteredJson<T>("/v1/embeddings", body, options),
  };

  readonly images = {
    generate: <T = unknown>(
      body: Record<string, unknown>,
      options?: MeteredRequestOptions,
    ) => this.meteredJson<T>("/v1/images/generations", body, options),
  };

  readonly audio = {
    speech: {
      create: (
        body: Record<string, unknown>,
        options?: MeteredRequestOptions,
      ) => this.metered("/v1/audio/speech", body, options),
    },
    transcriptions: {
      create: <T = unknown>(
        form: FormData,
        options?: MeteredRequestOptions,
      ) => this.meteredJson<T>("/v1/audio/transcriptions", form, options),
    },
    translations: {
      create: <T = unknown>(
        form: FormData,
        options?: MeteredRequestOptions,
      ) => this.meteredJson<T>("/v1/audio/translations", form, options),
    },
  };

  readonly models = {
    list: <T = unknown>(options?: RequestOptions) =>
      this.json<ListResponse<T>>("GET", "/v1/models", undefined, options),
  };

  readonly account = {
    retrieve: <T = unknown>(options?: RequestOptions) =>
      this.json<T>("GET", "/v1/account", undefined, options),
  };

  readonly wallet = {
    retrieve: <T = unknown>(options?: RequestOptions) =>
      this.json<T>("GET", "/v1/wallet", undefined, options),
  };

  readonly usage = {
    list: <T = unknown>(
      query: { after?: string; limit?: number } = {},
      options?: RequestOptions,
    ) =>
      this.json<ListResponse<T>>(
        "GET",
        this.withQuery("/v1/usage", query),
        undefined,
        options,
      ),
  };

  readonly billing = {
    createCheckout: <T = { url: string }>(
      productId: string,
      returnUrl: string,
      options?: RequestOptions,
    ) =>
      this.json<T>(
        "POST",
        "/v1/billing/checkout",
        { product_id: productId, return_url: returnUrl },
        options,
      ),
    checkout: {
      create: <T = { url: string }>(
        productId: string,
        returnUrl: string,
        options?: RequestOptions,
      ) =>
        this.json<T>(
          "POST",
          "/v1/billing/checkout",
          { product_id: productId, return_url: returnUrl },
          options,
        ),
    },
  };

  constructor(protected readonly options: ClientOptions) {
    this.baseURL = options.baseURL.replace(/\/$/, "");
    this.fetcher = options.fetch ?? globalThis.fetch.bind(globalThis);
  }

  protected async authenticatedHeaders(
    method: string,
    url: string,
    requestHeaders: Record<string, string> = {},
  ): Promise<{ headers: Headers; accessToken: string }> {
    const accessToken = await resolveToken(this.options.accessToken);
    const dpop = await this.options.dpopProof({
      url,
      method,
      accessToken,
    });
    const headers = new Headers(this.options.headers);
    for (const [name, value] of Object.entries(requestHeaders)) {
      headers.set(name, value);
    }
    headers.set("authorization", `DPoP ${accessToken}`);
    headers.set("dpop", dpop);
    return { headers, accessToken };
  }

  protected async raw(
    method: string,
    path: string,
    body?: BodyInit | Record<string, unknown>,
    options: RequestOptions = {},
  ): Promise<Response> {
    const url = `${this.baseURL}${path}`;
    const { headers } = await this.authenticatedHeaders(
      method,
      url,
      options.headers,
    );
    let encodedBody: BodyInit | undefined;
    if (body instanceof FormData || typeof body === "string") {
      encodedBody = body;
    } else if (body !== undefined) {
      headers.set("content-type", "application/json");
      encodedBody = JSON.stringify(body);
    }
    const response = await this.fetcher(url, {
      method,
      headers,
      body: encodedBody,
      signal: options.signal,
    });
    if (!response.ok) return throwResponseError(response);
    return response;
  }

  protected async json<T>(
    method: string,
    path: string,
    body?: BodyInit | Record<string, unknown>,
    options?: RequestOptions,
  ): Promise<T> {
    return (await this.raw(method, path, body, options)).json() as Promise<T>;
  }

  protected async metered(
    path: string,
    body: BodyInit | Record<string, unknown>,
    options: MeteredRequestOptions = {},
  ): Promise<Response> {
    const maxCost =
      options.maxCostMicrousd ?? this.options.defaultMaxCostMicrousd;
    if (!Number.isSafeInteger(maxCost) || (maxCost ?? 0) <= 0) {
      throw new Error(
        "A positive maxCostMicrousd is required for metered requests.",
      );
    }
    return this.raw("POST", path, body, {
      ...options,
      headers: {
        ...options.headers,
        [IDEMPOTENCY_HEADER]:
          options.idempotencyKey ?? generateIdempotencyKey(),
        [MAX_COST_HEADER]: String(maxCost),
      },
    });
  }

  protected async meteredJson<T>(
    path: string,
    body: BodyInit | Record<string, unknown>,
    options?: MeteredRequestOptions,
  ): Promise<T> {
    return (await this.metered(path, body, options)).json() as Promise<T>;
  }

  private withQuery(
    path: string,
    query: Record<string, string | number | undefined>,
  ): string {
    const parameters = new URLSearchParams();
    for (const [name, value] of Object.entries(query)) {
      if (value !== undefined) parameters.set(name, String(value));
    }
    const suffix = parameters.toString();
    return suffix ? `${path}?${suffix}` : path;
  }
}

import { Hono, type Context } from "hono";
import type { JWK } from "jose";
import { ModelAliasSchema } from "@notorganic/contracts";
import { TokenService } from "./auth";
import { GatewayError, openAIError } from "./errors";
import { PortkeyProxy } from "./proxy";
import type { RealtimeUpgrade } from "./realtime";
import type {
  GatewayConfig,
  VerifiedPrincipal,
} from "./types";

export interface GatewayDependencies {
  realtime?: RealtimeUpgrade;
}

interface Variables {
  principal: VerifiedPrincipal;
}

type GatewayHono = Hono<{ Variables: Variables }>;

function protectedRoute(
  app: GatewayHono,
  tokens: TokenService,
  method: "get" | "post" | "delete",
  path: string,
  scope: string | ((request: Request) => Promise<string>),
  handler: (c: Context<{ Variables: Variables }>) => Promise<Response>,
): void {
  app[method](path, async (c) => {
    const requiredScope =
      typeof scope === "function" ? await scope(c.req.raw) : scope;
    const principal = await tokens.authenticate(c.req.raw, requiredScope);
    c.set("principal", principal);
    return handler(c);
  });
}

async function inferenceScope(request: Request): Promise<string> {
  const contentType = request.headers.get("content-type") ?? "";
  let model: unknown;
  try {
    if (contentType.includes("application/json")) {
      model = ((await request.clone().json()) as { model?: unknown }).model;
    } else {
      model = (await request.clone().formData()).get("model");
    }
  } catch {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "The request body could not be parsed.",
      "invalid_body",
    );
  }
  const alias = ModelAliasSchema.safeParse(model);
  return alias.success ? `infer:${alias.data}` : "raw-model";
}

function queryLimit(value: string | undefined): number | undefined {
  if (value === undefined) return undefined;
  const limit = Number(value);
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "limit must be an integer from 1 through 100.",
      "invalid_limit",
      "limit",
    );
  }
  return limit;
}

export function createGateway(
  config: GatewayConfig,
  dependencies: GatewayDependencies = {},
): GatewayHono {
  const app = new Hono<{ Variables: Variables }>();
  const tokens = new TokenService(config);
  const proxy = new PortkeyProxy(config);

  app.onError((error, c) => openAIError(c, error));
  app.get("/healthz", async (c) => {
    try {
      await config.store.healthCheck?.();
      return c.json({ ok: true });
    } catch {
      return c.json({ ok: false }, 503);
    }
  });

  app.post("/v1/auth/token/exchange", async (c) => {
    const body = await c.req.json<{
      assertion?: unknown;
      dpop_jwk?: JWK;
      scope?: unknown;
    }>();
    if (typeof body.assertion !== "string") {
      throw new GatewayError(
        400,
        "invalid_request_error",
        "assertion is required.",
        "missing_assertion",
        "assertion",
      );
    }
    return c.json(
      await tokens.exchange({
        assertion: body.assertion,
        dpopJwk: body.dpop_jwk,
        requestedScope:
          typeof body.scope === "string" ? body.scope : undefined,
      }),
    );
  });

  protectedRoute(
    app,
    tokens,
    "post",
    "/v1/responses",
    inferenceScope,
    async (c) => {
      let body: { store?: unknown };
      try {
        body = (await c.req.raw.clone().json()) as { store?: unknown };
      } catch {
        throw new GatewayError(
          400,
          "invalid_request_error",
          "The request body could not be parsed.",
          "invalid_body",
        );
      }
      return proxy.metered({
        request: c.req.raw,
        principal: c.get("principal"),
        upstreamPath: "/responses",
        feature: "responses",
        persistResponse: body.store !== false,
      });
    },
  );
  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/responses/:responseId",
    "responses:read",
    async (c) => {
      const response = await config.store.getResponse({
        accountId: c.get("principal").accountId,
        responseId: c.req.param("responseId")!,
      });
      if (!response) {
        throw new GatewayError(
          404,
          "invalid_request_error",
          "Response not found.",
          "not_found",
        );
      }
      return c.json(response);
    },
  );
  protectedRoute(
    app,
    tokens,
    "delete",
    "/v1/responses/:responseId",
    "responses:delete",
    async (c) => {
      const responseId = c.req.param("responseId")!;
      const deleted = await config.store.deleteResponse({
        accountId: c.get("principal").accountId,
        responseId,
      });
      if (!deleted) {
        throw new GatewayError(
          404,
          "invalid_request_error",
          "Response not found.",
          "not_found",
        );
      }
      return c.json({ id: responseId, object: "response.deleted", deleted: true });
    },
  );
  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/responses/:responseId/input_items",
    "responses:read",
    async (c) =>
      c.json(
        await config.store.listInputItems({
          accountId: c.get("principal").accountId,
          responseId: c.req.param("responseId")!,
          after: c.req.query("after"),
          limit: queryLimit(c.req.query("limit")),
        }),
      ),
  );

  const inferenceRoutes = [
    {
      path: "/v1/chat/completions",
      upstream: "/chat/completions",
      feature: "chat",
    },
    {
      path: "/v1/embeddings",
      upstream: "/embeddings",
      feature: "embeddings",
    },
    {
      path: "/v1/images/generations",
      upstream: "/images/generations",
      feature: "images",
    },
    {
      path: "/v1/audio/speech",
      upstream: "/audio/speech",
      feature: "audio_speech",
    },
    {
      path: "/v1/audio/transcriptions",
      upstream: "/audio/transcriptions",
      feature: "audio_transcription",
    },
    {
      path: "/v1/audio/translations",
      upstream: "/audio/translations",
      feature: "audio_translation",
    },
  ] as const;
  for (const route of inferenceRoutes) {
    protectedRoute(app, tokens, "post", route.path, inferenceScope, (c) =>
      proxy.metered({
        request: c.req.raw,
        principal: c.get("principal"),
        upstreamPath: route.upstream,
        feature: route.feature,
      }),
    );
  }

  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/models",
    "",
    async (c) => {
      const aliases = config.enabledAliases ?? [
        "fast",
        "balanced",
        "reasoning",
        "vision",
        "embedding",
        "image",
        "audio",
        "realtime",
      ];
      return c.json({
        object: "list",
        data: aliases.map((id) => ({
          id,
          object: "model",
          owned_by: "notorganic",
        })),
      });
    },
  );
  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/account",
    "",
    async (c) =>
      c.json(
        await config.store.getAccount({
          accountId: c.get("principal").accountId,
        }),
      ),
  );
  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/wallet",
    "wallet:read",
    async (c) =>
      c.json(
        await config.store.getWallet({
          accountId: c.get("principal").accountId,
        }),
      ),
  );
  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/usage",
    "usage:read",
    async (c) =>
      c.json(
        await config.store.listUsage({
          accountId: c.get("principal").accountId,
          after: c.req.query("after"),
          limit: queryLimit(c.req.query("limit")),
        }),
      ),
  );
  protectedRoute(
    app,
    tokens,
    "post",
    "/v1/billing/checkout",
    "billing:checkout",
    async (c) => {
      const body = await c.req.json<{ return_url?: unknown; product_id?: unknown }>();
      if (
        typeof body.return_url !== "string" ||
        !body.return_url.startsWith("https://")
      ) {
        throw new GatewayError(
          400,
          "invalid_request_erro…3635 tokens truncated…xpiresAtSeconds: now + DPOP_CLOCK_SKEW_SECONDS * 2,
      });
      if (!consumed) {
        throw new Error("proof replay");
      }
    } catch {
      throw new GatewayError(
        401,
        "authentication_error",
        "The DPoP proof is invalid or has been replayed.",
        "invalid_dpop_proof",
      );
    }
  }

}

