	migrated: boolean;
}

async function providerJson<T>(
	path: string,
	init?: RequestInit,
	fetcher: typeof fetch = fetch,
): Promise<T> {
	const response = await fetcher(`/api/dio/provider/${path}`, init);
	const body = await response.json().catch(() => ({}));
	if (!response.ok) {
		const message =
			typeof body?.error?.message === "string"
				? body.error.message
				: typeof body?.message === "string"
					? body.message
					: `Not Organic request failed (${response.status})`;
		throw new Error(message);
	}
	return body as T;
}

export function getNotOrganicAccount(fetcher?: typeof fetch): Promise<NotOrganicAccount> {
	return providerJson("account", undefined, fetcher);
}

export function getNotOrganicWallet(fetcher?: typeof fetch): Promise<NotOrganicWallet> {
	return providerJson("wallet", undefined, fetcher);
}

export function getNotOrganicUsage(
	options: { after?: string; limit?: number } = {},
	fetcher?: typeof fetch,
): Promise<NotOrganicUsage> {
	const query = new URLSearchParams();
	if (options.after) query.set("after", options.after);
	if (options.limit !== undefined) query.set("limit", String(options.limit));
	return providerJson(`usage${query.size ? `?${query}` : ""}`, undefined, fetcher);
}

export function createNotOrganicCheckout(
	returnUrl: string,
	fetcher?: typeof fetch,
): Promise<NotOrganicCheckout> {
	return providerJson(
		"checkout",
		{
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ return_url: returnUrl }),
		},
		fetcher,
	);
}

export function migrateLegacyDioValue(
	legacyProof: string,
	fetcher?: typeof fetch,
): Promise<NotOrganicLegacyMigrationResult> {
	if (!legacyProof.trim()) {
		return Promise.reject(new TypeError("A legacy Dio proof is required."));
	}
	return providerJson(
		"migrate",
		{
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ legacy_proof: legacyProof }),
		},
		fetcher,
	);
}

export function isNotOrganicProvider(provider: string): boolean {
	return provider === NOTORGANIC_PROVIDER_ID;
}

export function isNotOrganicFeatureEnabled(): boolean {
	let configured: string | undefined;
	if (typeof import.meta.env !== "undefined") {
		configured = import.meta.env.VITE_NOTORGANIC_PROVIDER_ENABLED;
	} else if (typeof process !== "undefined") {
		configured = process.env.VITE_NOTORGANIC_PROVIDER_ENABLED;
	}
	if (configured === "true") return true;
	if (configured === "false") return false;
	return false;
}

function currentOrigin(): string {
	return typeof globalThis.location?.origin === "string" && globalThis.location.origin
		? globalThis.location.origin
		: "http://localhost";
}
export const NOTORGANIC_IDEMPOTENCY_HEADER = "idempotency-key";
export const NOTORGANIC_MAX_COST_HEADER = "x-notorganic-max-cost-microusd";

