function requestId(): string {
	return `keating_${crypto.randomUUID()}`;
}

/**
 * Small internal adapter matching the hosted SDK's HTTP contract. Keating keeps
 * this local until @notorganic/sdk is published; callers still send DPoP,
 * idempotency, and microusd cost headers exactly as the hosted gateway expects.
 */
export class NotOrganicFetchAdapter {
	private readonly baseUrl: string;
	private readonly fetcher: typeof globalThis.fetch;

	constructor(private readonly options: NotOrganicFetchAdapterOptions) {
		this.baseUrl = options.baseUrl.replace(/\/+$/, "");
		this.fetcher = options.fetch ?? globalThis.fetch;
	}

	async request(path: string, options: NotOrganicRequestOptions = {}): Promise<Response> {
		const method = (options.method ?? "GET").toUpperCase();
		const url = `${this.baseUrl}${path.startsWith("/") ? path : `/${path}`}`;
		const headers = new Headers(options.headers);
		headers.set("authorization", `DPoP ${this.options.session.accessToken}`);
		headers.set("dpop", await this.options.session.createDpopProof({
			method,
			url,
			accessToken: this.options.session.accessToken,
		}));

		if (options.maxCostMicrousd !== undefined) {
			if (!Number.isSafeInteger(options.maxCostMicrousd) || options.maxCostMicrousd <= 0) {
				throw new TypeError("maxCostMicrousd must be a positive safe integer");
			}
			headers.set(NOTORGANIC_MAX_COST_HEADER, String(options.maxCostMicrousd));
			headers.set(NOTORGANIC_IDEMPOTENCY_HEADER, options.idempotencyKey?.trim() || requestId());
		}

		return this.fetcher(url, {
			method,
			headers,
			body: options.body,
			signal: options.signal,
			redirect: "error",
			...(options.body ? { duplex: "half" } : {}),
		} as RequestInit);
	}
}

import type { H3Event } from "h3";
import {
	NotOrganicFetchAdapter,
	type NotOrganicProductSession,
} from "./fetch-adapter";

export const NOTORGANIC_SESSION_ADAPTER_CONTEXT_KEY = "notOrganicSessionAdapter";
export const NOTORGANIC_MIGRATION_ADAPTER_CONTEXT_KEY = "notOrganicLegacyMigrationAdapter";
export const NOTORGANIC_AUTH_OPERATIONAL_BLOCKER =
	"Not Organic hosted access requires a deployment-owned ATProto/Better Auth product-session adapter. Keating does not yet have durable server auth, so browser DID or email claims are intentionally rejected.";

export class NotOrganicOperationalError extends Error {
	readonly statusCode = 503;
	readonly code = "notorganic_auth_adapter_unavailable";

	constructor(message = NOTORGANIC_AUTH_OPERATIONAL_BLOCKER) {
		super(message);
	}
}

export interface NotOrganicSessionRequest {
	feature: string;
}

export interface NotOrganicSessionAdapter {
	/**
	 * Resolve a product capability from a server-validated session. Implementors
	 * own assertion signing/exchange, refresh, revocation, and DPoP key custody.
	 */
	getProductSession(
		event: H3Event,
		request: NotOrganicSessionRequest,
	): Promise<NotOrganicProductSession | null>;
}

export interface NotOrganicLegacyMigrationAdapter {
	/**
	 * Migrate legacy Dio value only after `session` has been validated. The
	 * adapter must verify the old entitlement/credential server-side; email or
	 * DID strings supplied by the browser are not identity evidence.
	 */
	migrateLegacyDio(input: {
		event: H3Event;
		session: NotOrganicProductSession;
		legacyProof: string;
	}): Promise<{ migrated: boolean }>;
}

type NotOrganicEventContext = H3Event["context"] & {
	[NOTORGANIC_SESSION_ADAPTER_CONTEXT_KEY]?: NotOrganicSessionAdapter;
	[NOTORGANIC_MIGRATION_ADAPTER_CONTEXT_KEY]?: NotOrganicLegacyMigrationAdapter;
};

export function getNotOrganicSessionAdapter(event: H3Event): NotOrganicSessionAdapter {
	const adapter = (event.context as NotOrganicEventContext)[NOTORGANIC_SESSION_ADAPTER_CONTEXT_KEY];
	if (!adapter) throw new NotOrganicOperationalError();
	return adapter;
}

export function getNotOrganicLegacyMigrationAdapter(
	event: H3Event,
): NotOrganicLegacyMigrationAdapter {
	const adapter = (event.context as NotOrganicEventContext)[NOTORGANIC_MIGRATION_ADAPTER_CONTEXT_KEY];
	if (!adapter) {
		throw new NotOrganicOperationalError(
			"Legacy Dio migration requires a deployment adapter that verifies the old entitlement before moving value.",
		);
	}
	return adapter;
}

export async function requireNotOrganicProductSession(
	event: H3Event,
	feature: string,
): Promise<NotOrganicProductSession> {
	const session = await getNotOrganicSessionAdapter(event).getProductSession(event, { feature });
	if (!session) {
		throw new NotOrganicOperationalError(
			"Sign in through the deployment-owned Keating product session before using Not Organic hosted access.",
		);
	}
	return session;
}

export interface NotOrganicServerConfig {
	enabled: boolean;
	gatewayBaseUrl: string;
	maxCostMicrousd: number;
	legacyDioCompatibility: boolean;
}

function positiveIntegerEnv(name: string, env: NodeJS.ProcessEnv): number {
	const value = Number(env[name]);
	if (!Number.isSafeInteger(value) || value <= 0) {
		throw new NotOrganicOperationalError(`${name} must be configured as a positive integer.`);
	}
	return value;
}

export function isNotOrganicHostedEnabled(env: NodeJS.ProcessEnv = process.env): boolean {
	return env.NOTORGANIC_PROVIDER_ENABLED === "true";
}

export function getNotOrganicServerConfig(env: NodeJS.ProcessEnv = process.env): NotOrganicServerConfig {
	if (!isNotOrganicHostedEnabled(env)) {
		return {
			enabled: false,
			gatewayBaseUrl: "",
			maxCostMicrousd: 0,
			legacyDioCompatibility: true,
		};
	}
	const gatewayBaseUrl = env.NOTORGANIC_GATEWAY_URL?.trim().replace(/\/+$/, "");
	if (!gatewayBaseUrl || !gatewayBaseUrl.startsWith("https://")) {
		throw new NotOrganicOperationalError(
			"NOTORGANIC_GATEWAY_URL must be configured as an HTTPS server-only URL.",
		);
	}
	let gatewayUrl: URL;
	try {
		gatewayUrl = new URL(gatewayBaseUrl);
	} catch {
		throw new NotOrganicOperationalError(
			"NOTORGANIC_GATEWAY_URL must be a valid HTTPS gateway origin.",
		);
	}
	if (gatewayUrl.pathname !== "/" || gatewayUrl.search || gatewayUrl.hash) {
		throw new NotOrganicOperationalError(
			"NOTORGANIC_GATEWAY_URL must be the gateway origin without a /v1 path, query, or fragment.",
		);
	}
	return {
		enabled: true,
		gatewayBaseUrl: gatewayUrl.origin,
		maxCostMicrousd: positiveIntegerEnv("NOTORGANIC_MAX_COST_MICROUSD", env),
		legacyDioCompatibility: env.DIO_LEGACY_COMPATIBILITY !== "false",
	};
}

export async function createNotOrganicServerClient(
	event: H3Event,
	feature: string,
	config = getNotOrganicServerConfig(),
): Promise<NotOrganicFetchAdapter> {
	if (!config.enabled) {
		throw new NotOrganicOperationalError("Not Organic hosted access is disabled.");
	}
	return new NotOrganicFetchAdapter({
		baseUrl: config.gatewayBaseUrl,
		session: await requireNotOrganicProductSession(event, feature),
	});
}
# Not Organic hosted provider deployment

The browser integration is feature-gated with:

- `VITE_NOTORGANIC_PROVIDER_ENABLED=true`
- `NOTORGANIC_PROVIDER_ENABLED=true`

The Nitro server additionally requires:

- `NOTORGANIC_GATEWAY_URL` — HTTPS gateway origin, without `/v1`
- `NOTORGANIC_MAX_COST_MICROUSD` — positive per-request reservation ceiling
- `DIO_LEGACY_COMPATIBILITY` — defaults to `true` for the one-release Dio proxy window

Enabling those variables is not sufficient to authenticate a user. A Nitro
middleware/plugin must put a `NotOrganicSessionAdapter` on each authenticated
request at `event.context.notOrganicSessionAdapter`. That adapter must:

1. Resolve a durable, server-validated Better Auth session.
2. Resolve its linked ATProto DID without accepting a browser-provided DID or
   email as proof.
3. Sign and exchange the 60-second Keating product assertion.
4. Retain the five-minute capability token and DPoP private key server-side.
5. Implement refresh, revocation, and session-version checks.

Until Keating has that durable auth/storage deployment, hosted calls return
`503 notorganic_auth_adapter_unavailable`. This is intentional.

Legacy balance migration has a separate
`event.context.notOrganicLegacyMigrationAdapter` boundary. It receives a
validated product session plus the old proof and must verify the legacy
entitlement server-side before moving value. The browser's saved email, DID, or
mere possession flag is never identity evidence.
import { describe, expect, it } from "bun:test";
import { mockEvent } from "h3";
import {
	NOTORGANIC_DEFAULT_MODEL,
	NOTORGANIC_MODEL_ALIAS,
	NOTORGANIC_PROVIDER_ID,
	createNotOrganicCheckout,
	getNotOrganicUsage,
	isNotOrganicProvider,
	migrateLegacyDioValue,
	notOrganicOpenAiBaseUrl,
} from "../notorganic-provider";
import {
	NOTORGANIC_IDEMPOTENCY_HEADER,
	NOTORGANIC_MAX_COST_HEADER,
	NotOrganicFetchAdapter,
} from "../notorganic-provider/fetch-adapter";
import {
	NOTORGANIC_AUTH_OPERATIONAL_BLOCKER,
	NotOrganicOperationalError,
	getNotOrganicServerConfig,
} from "../notorganic-provider/server";

describe("Not Organic provider definition", () => {
	it("uses the stable balanced alias and same-origin Dio compatibility path", () => {
		expect(NOTORGANIC_DEFAULT_MODEL.id).toBe(NOTORGANIC_MODEL_ALIAS);
		expect(NOTORGANIC_DEFAULT_MODEL.provider).toBe(NOTORGANIC_PROVIDER_ID);
		expect(notOrganicOpenAiBaseUrl("https://keating.test/")).toBe(
			"https://keating.test/api/dio/openai/v1",
		);
		expect(isNotOrganicProvider("notorganic")).toBe(true);
		expect(isNotOrganicProvider("dio")).toBe(false);
	});
});

describe("Not Organic SDK-compatible fetch adapter", () => {
	it("keeps the capability server-side and supplies DPoP, cost, and idempotency headers", async () => {
		let observed: { url?: string; init?: RequestInit } = {};
		const adapter = new NotOrganicFetchAdapter({
			baseUrl: "https://provider.test",
			session: {
				accountId: "did:plc:alice",
				accessToken: "server-capability",
				createDpopProof: async ({ method, url, accessToken }) =>
					`${method}:${url}:${accessToken}`,
			},
			fetch: (async (url, init) => {
				observed = { url: String(url), init };
				return Response.json({ ok: true });
			}) as typeof fetch,
		});

		await adapter.request("/v1/chat/completions", {
			method: "POST",
			body: JSON.stringify({ model: "balanced" }),
			headers: { "content-type": "application/json" },
			maxCostMicrousd: 50_000,
			idempotencyKey: "idem-keating",
		});

		const headers = new Headers(observed.init?.headers);
		expect(observed.url).toBe("https://provider.test/v1/chat/completions");
		expect(headers.get("authorization")).toBe("DPoP server-capability");
		expect(headers.get("dpop")).toContain("server-capability");
		expect(headers.get(NOTORGANIC_MAX_COST_HEADER)).toBe("50000");
		expect(headers.get(NOTORGANIC_IDEMPOTENCY_HEADER)).toBe("idem-keating");
	});
});

describe("Not Organic browser resource client", () => {
	it("calls usage and checkout through same-origin product routes", async () => {
		const calls: string[] = [];
		const fetcher = (async (input, init) => {
			calls.push(`${init?.method ?? "GET"} ${String(input)}`);
			return Response.json({ object: "list", data: [] });
		}) as typeof fetch;

		await getNotOrganicUsage({ after: "cursor", limit: 10 }, fetcher);
		await createNotOrganicCheckout("https://keating.test/settings", fetcher);
		await migrateLegacyDioValue("legacy-credential-proof", fetcher);

		expect(calls).toEqual([
			"GET /api/dio/provider/usage?after=cursor&limit=10",
			"POST /api/dio/provider/checkout",
			"POST /api/dio/provider/migrate",
		]);
	});
});

describe("Not Organic operational config", () => {
	it("does not invent a product session when auth deployment is absent", () => {
		expect(NOTORGANIC_AUTH_OPERATIONAL_BLOCKER).toContain("Better Auth");
		expect(() =>
			getNotOrganicServerConfig({
				NOTORGANIC_PROVIDER_ENABLED: "true",
				NOTORGANIC_GATEWAY_URL: "https://provider.test",
			} as NodeJS.ProcessEnv),
		).toThrow(NotOrganicOperationalError);
	});

	it("requires the server-only gateway and a positive request cap", () => {
		expect(
			getNotOrganicServerConfig({
				NOTORGANIC_PROVIDER_ENABLED: "true",
				NOTORGANIC_GATEWAY_URL: "https://provider.test",
				NOTORGANIC_MAX_COST_MICROUSD: "50000",
			} as NodeJS.ProcessEnv),
		).toEqual({
			enabled: true,
			gatewayBaseUrl: "https://provider.test",
			maxCostMicrousd: 50000,
			legacyDioCompatibility: true,
		});
	});
});

describe("Not Organic Nitro routing", () => {
	it("replaces the browser marker with the server session capability", async () => {
		const previous = {
			enabled: process.env.NOTORGANIC_PROVIDER_ENABLED,
			url: process.env.NOTORGANIC_GATEWAY_URL,
			cost: process.env.NOTORGANIC_MAX_COST_MICROUSD,
		};
		const originalFetch = globalThis.fetch;
		let observed: { url?: string; headers?: Headers } = {};
		let feature = "";
		process.env.NOTORGANIC_PROVIDER_ENABLED = "true";
		process.env.NOTORGANIC_GATEWAY_URL = "https://provider.test";
		process.env.NOTORGANIC_MAX_COST_MICROUSD = "75000";
		globalThis.fetch = (async (input, init) => {
			observed = { url: String(input), headers: new Headers(init?.headers) };
			return new Response("data: [DONE]\n\n", {
				headers: { "content-type": "text/event-stream" },
			});
		}) as typeof fetch;

		try {
			const handler = (await import("../../server/api/dio/openai/[...path]")).default;
			const event = mockEvent(
				new Request("https://keating.test/api/dio/openai/v1/chat/completions", {
					method: "POST",
					headers: {
						"content-type": "application/json",
						"x-keating-provider": "notorganic",
						authorization: "Bearer browser-placeholder",
					},
					body: JSON.stringify({ model: "balanced", messages: [] }),
				}),
			);
			event.context.notOrganicSessionAdapter = {
				getProductSession: async (_event: unknown, request: { feature: string }) => {
					feature = request.feature;
					return {
						accountId: "did:plc:alice",
						accessToken: "server-capability",
						createDpopProof: async () => "server-proof",
					};
				},
			};

			const response = await handler(event) as Response;
			expect(response.status).toBe(200);
			expect(observed.url).toBe("https://provider.test/v1/chat/completions");
			expect(observed.headers?.get("authorization")).toBe("DPoP server-capability");
			expect(observed.headers?.get("authorization")).not.toContain("browser-placeholder");
			expect(observed.headers?.get(NOTORGANIC_MAX_COST_HEADER)).toBe("75000");
			expect(observed.headers?.get(NOTORGANIC_IDEMPOTENCY_HEADER)).toMatch(/^keating_/);
			expect(feature).toBe("keating:web-chat");
		} finally {
			globalThis.fetch = originalFetch;
			restoreEnv("NOTORGANIC_PROVIDER_ENABLED", previous.enabled);
			restoreEnv("NOTORGANIC_GATEWAY_URL", previous.url);
			restoreEnv("NOTORGANIC_MAX_COST_MICROUSD", previous.cost);
		}
	});
});

function restoreEnv(name: string, value: string | undefined): void {
	if (value === undefined) {
		delete process.env[name];
	} else {
		process.env[name] = value;
	}
}

