  {
    readonly amountMicrousd: Microusd;
    readonly cadence: "monthly" | "once";
    readonly productScope: ProductId | null;
    readonly rolloverIntervals: 0 | 1 | null;
  }
>;

export type GrantCatalogId = keyof typeof GRANT_CATALOG;

export interface GrantPeriod {
  readonly startAt: number;
  readonly endAt: number;
}

export interface GrantLotSeed {
  readonly sourceId: GrantCatalogId;
  readonly deduplicationKey: string;
  readonly amountMicrousd: Microusd;
  readonly productScope: ProductId | null;
  readonly expiresAt: number | null;
}

export function materializeGrant(
  grantId: GrantCatalogId,
  period: GrantPeriod,
  deduplicationKey: string,
  nextPeriodEndAt?: number,
): GrantLotSeed {
  if (period.endAt <= period.startAt) {
    throw new RangeError("grant period must have positive duration");
  }
  const grant = GRANT_CATALOG[grantId];
  let expiresAt: number | null;
  if (grant.rolloverIntervals === null) {
    expiresAt = null;
  } else if (grant.rolloverIntervals === 0) {
    expiresAt = period.endAt;
  } else {
    if (
      nextPeriodEndAt === undefined ||
      nextPeriodEndAt <= period.endAt
    ) {
      throw new RangeError(
        "one-interval rollover requires the following period end",
      );
    }
    expiresAt = nextPeriodEndAt;
  }
  return {
    sourceId: grantId,
    deduplicationKey,
    amountMicrousd: grant.amountMicrousd,
    productScope: grant.productScope,
    expiresAt,
  };
}

/**
 * The partner grant is issued once for the second Pro seat in a billing period.
 * Persistence uses this deterministic key as its unique idempotency key.
 */
export function interleaveProPartnerGrantKey(
  subscriptionId: string,
  partnerDid: string,
  periodStartAt: number,
): string {
  if (!subscriptionId || !partnerDid.startsWith("did:")) {
    throw new TypeError("subscription and partner DID are required");
  }
  return `interleave-pro-partner:${subscriptionId}:${partnerDid}:${periodStartAt}`;
}

