export async function discoverCustomProviderModels(provider: KeatingCustomProvider): Promise<Model<Api>[]> {
	if (AUTO_DISCOVERY_TYPES.has(provider.type)) {
		let models: Model<Api>[];
		switch (provider.type) {
			case "ollama":
				models = await discoverOllamaModels(provider.baseUrl);
				break;
			case "llama.cpp":
				models = await discoverLlamaCppModels(provider.baseUrl, provider.apiKey);
				break;
			case "vllm":
				models = await discoverVllmModels(provider.baseUrl, provider.apiKey);
				break;
			case "lmstudio":
				models = await discoverLmStudioModels(provider.baseUrl);
				break;
			default:
				models = [];
		}

		return models.map((model) => ({ ...model, provider: provider.name }));
	}

	if (OPENAI_COMPATIBLE_TYPES.has(provider.type)) {
		const discovered = await discoverOpenAiCompatibleModels(provider);
		return discovered.models;
	}

	return (provider.models || []).map((model) => ({
		...model,
		provider: provider.name,
		baseUrl: model.baseUrl || provider.baseUrl,
		api: model.api || manualProviderApi(provider.type),
	}));
}

export async function getCustomProviders(): Promise<KeatingCustomProvider[]> {
	return (await getAppStorage().customProviders.getAll()) as KeatingCustomProvider[];
}

export async function syncCustomProviderKeys(): Promise<void> {
	const storage = getAppStorage();
	const providers = await getCustomProviders();

	await Promise.all(
		providers.map(async (provider) => {
			if (provider.apiKey) {
				await storage.providerKeys.set(provider.name, provider.apiKey);
			}
		}),
	);
}

export async function getProviderApiKey(providerName: string): Promise<string | undefined> {
	if (providerName === NOTORGANIC_PROVIDER_ID && isNotOrganicFeatureEnabled()) {
		// Pi's OpenAI-compatible transport expects a non-empty key. This value is
		// only a same-origin transport marker; the Nitro route strips it and uses
		// the deployment-owned product session capability instead.
		return "notorganic-product-session";
	}
	const oauthId = providerToOAuthId(providerName);
	if (oauthId) {
		const token = await getOAuthAccessToken(oauthId);
		if (token) return token;
	}

	const storage = getAppStorage();
	const storedKey = await storage.providerKeys.get(providerName);
	if (storedKey) return storedKey;

	const customProviders = await getCustomProviders();
	return customProviders.find((provider) => provider.name === providerName)?.apiKey;
}

const FALLBACK_CHAT_MODEL_IDS: Record<string, string[]> = {
	[NOTORGANIC_PROVIDER_ID]: [NOTORGANIC_DEFAULT_MODEL.id],
	[DIO_PROVIDER_ID]: [DIO_DEFAULT_MODEL.id],
	openai: ["gpt-5.5", "gpt-5.5-pro", "gpt-5.4", "gpt-5.3-chat-latest", "gpt-5.2", "gpt-5.1", "gpt-5"],
	anthropic: ["claude-sonnet-4-6", "claude-opus-4-8", "claude-opus-4-7", "claude-sonnet-4-5", "claude-haiku-4-5"],
	google: ["gemini-3.1-pro-preview", "gemini-3.5-flash", "gemini-3-pro-preview", "gemini-2.5-pro"],
};

function providerNeedsKey(provider: string): boolean {
	return provider !== "browser";
}

function preferredModelForProvider(models: Array<Model<Api>>, provider: string): Model<Api> | undefined {
	const providerModels = models.filter((model) => model.provider === provider);
	const ids = FALLBACK_CHAT_MODEL_IDS[provider] ?? [];
	for (const id of ids) {
		const found = providerModels.find((model) => model.id === id);
		if (found) return found;
	}
	return providerModels[0];
}

export async function resolveAvailableChatModel(current: Model<Api>): Promise<Model<Api>> {
	if (!providerNeedsKey(current.provider) || await getProviderApiKey(current.provider)) {
		return current;
	}

	const models = await getSelectableModels();
	for (const provider of [NOTORGANIC_PROVIDER_ID, DIO_PROVIDER_ID, "openai", "anthropic", "google"]) {
		if (!(await getProviderApiKey(provider))) continue;
		const model = preferredModelForProvider(models, provider);
		if (model) return model;
	}

	return current;
}

export const UNKNOWN_COST = {
	input: 0,
	output: 0,
	cacheRead: 0,
	cacheWrite: 0,
} as const;

export const UNKNOWN_CONTEXT_WINDOW = 8192;
export const UNKNOWN_MAX_TOKENS = 4096;

function keatingCompatibilityModels(filter?: (provider: string) => boolean): Array<Model<Api>> {
	const models: Array<Model<Api>> = [];
	const minimaxModels: Array<[id: string, name: string]> = [
		["MiniMax-M3", "MiniMax-M3"],
		["minimax-m2.7-highspeed", "MiniMax M2.7 Highspeed"],
	];
	const maybeAdd = (provider: string, baseUrl: string) => {
		if (filter && !filter(provider)) return;
		for (const [id, name] of minimaxModels) {
			models.push({
				id,
				name,
				api: "openai-completions" as Api,
				provider,
				baseUrl,
				reasoning: true,
				input: ["text"],
				cost: UNKNOWN_COST,
				contextWindow: 1_000_000,
				maxTokens: 4096,
			});
		}
	};
	maybeAdd("minimax", "https://api.minimax.io/v1");
	maybeAdd("minimax-cn", "https://api.minimaxi.com/v1");
	return models;
}

export async function getSelectableModels(
	filter?: (provider: string) => boolean,
): Promise<Array<Model<Api>>> {
	const models: Array<Model<Api>> = [];

	if (isNotOrganicFeatureEnabled() && (!filter || filter(NOTORGANIC_PROVIDER_ID))) {
		models.push(NOTORGANIC_DEFAULT_MODEL);
	}
	if (!filter || filter(DIO_PROVIDER_ID)) {
		models.push(DIO_DEFAULT_MODEL);
	}

	for (const provider of getProviders()) {
		if (!filter || filter(provider)) {
			models.push(...(getModels(provider as any) as Array<Model<Api>>));
		}
	}

	models.push(...keatingCompatibilityModels(filter));

	const customProviders = await getCustomProviders();
	const customModels = await Promise.all(
		customProviders.map(async (provider) => {
			try {
				return await discoverCustomProviderModels(provider);
			} catch (error) {
				console.warn(`Skipping unavailable provider ${provider.name}:`, error);
				return [];
			}
		}),
	);

	models.push(...customModels.flat());
	return models;
}

export function buildSavedModel(saved: any): Model<Api> {
	return {
		id: saved.id,
		name: saved.name,
		api: saved.api as Api,
		provider: saved.provider,
		baseUrl: saved.baseUrl || "",
		reasoning: saved.reasoning,
		input: saved.vision ? (["text", "image"] as Array<"text" | "image">) : (["text"] as Array<"text" | "image">),
		cost: UNKNOWN_COST,
		contextWindow: UNKNOWN_CONTEXT_WINDOW,
		maxTokens: UNKNOWN_MAX_TOKENS,
	};
}
import {
	createAssistantMessageEventStream,
	type Api,
	type AssistantMessage,
	type Context,
	type Model,
	type SimpleStreamOptions,
} from "@earendil-works/pi-ai";
import { streamSimple } from "@earendil-works/pi-ai/compat";
import { normalizeToolCallStream } from "../keating/tool-call-normalizer";
import { streamWithApiRetry } from "../keating/api-retry";
import { chatProxyBaseUrl, proxyTargetHeader, shouldProxyModel } from "../lib/provider-proxy";
import { DIO_DEFAULT_MODEL } from "../dio-provider";
import {
	isNotOrganicFeatureEnabled,
	isNotOrganicProvider,
	NOTORGANIC_DEFAULT_MODEL,
	NOTORGANIC_FEATURE,
	NOTORGANIC_PROVIDER_ID,
} from "../notorganic-provider";
import {
	applyGoogleSearchGrounding,
	applyProviderWebSearch,
	resolveProviderWebSearchRoute,
} from "../keating/provider-web-search";
import { signalHostedSearchActivation } from "../keating/search";

// Compatibility exports for existing integrations and tests. New routing should
// prefer applyProviderWebSearch so capability negotiation stays centralized.
export { applyGoogleSearchGrounding, applyProviderWebSearch };
import { getProviderApiKey } from "../lib/provider-models";
import { localModel, getModelName, getModelId } from "../stores/local-model";

export const DEFAULT_MODEL = isNotOrganicFeatureEnabled()
	? NOTORGANIC_DEFAULT_MODEL
	: DIO_DEFAULT_MODEL;

export function withProviderWebSearch(
	options: SimpleStreamOptions | undefined,
	model: Model<Api>,
	hasApiKey: boolean,
): SimpleStreamOptions | undefined {
	if (model.provider !== "google" && model.provider !== "openai" && model.provider !== "anthropic") {
		return options;
	}
	let signalled = false;

	return {
		...options,
		onPayload: async (payload, payloadModel) => {
			const userPayload = await options?.onPayload?.(payload, payloadModel);
			const nextPayload = userPayload ?? payload;
			const groundedPayload = applyProviderWebSearch(nextPayload, payloadModel, hasApiKey);
			if (groundedPayload !== undefined && !signalled) {
				signalled = true;
				signalHostedSearchActivation(resolveProviderWebSearchRoute(payloadModel, hasApiKey));
			}
			return groundedPayload ?? userPayload;
		},
	};
}

function createBrowserStreamFn() {
	return async (_model: Model<Api>, context: Context, options?: SimpleStreamOptions) => {
		const stream = createAssistantMessageEventStream();
		const abortSignal = options?.signal;

		const defaultFields = {
			api: "browser" as const,
			provider: "browser" as const,
			model: getModelId(),
			usage: {
				input: 0,
				output: 0,
				cacheRead: 0,
				cacheWrite: 0,
				totalTokens: 0,
				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
			},
		};

		(async () => {
			try {
				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				const userMessages = context.messages
					.filter((m): m is Extract<typeof m, { role: "user" }> => m.role === "user")
					.map((m) => {
						const content = m.content;
						if (typeof content === "string") return content;
						return content
							.filter((c): c is Extract<typeof c, { type: "text" }> => c.type === "text")
							.map((c) => c.text)
							.join("\n");
					});

				const systemPrompt = context.systemPrompt || "";
				const conversationHistory = userMessages.join("\n\n");
				const fullPrompt = systemPrompt
					? `${systemPrompt}\n\n${conversationHistory}`
					: conversationHistory;

				const partialMessage: AssistantMessage = {
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: "" }],
					stopReason: "stop",
					timestamp: Date.now(),
				};

				stream.push({ type: "start", partial: partialMessage });
				stream.push({ type: "text_start", contentIndex: 0, partial: partialMessage });

				const response = await localModel.generate(
					fullPrompt,
					{ max_length: options?.maxTokens ?? 1024, temperature: options?.temperature ?? 0.7 },
					(token: string) => {
						const textBlock = partialMessage.content[0];
						if (textBlock.type === "text") textBlock.text += token;
						stream.push({ type: "text_delta", contentIndex: 0, delta: token, partial: partialMessage });
					},
				);

				if (abortSignal?.aborted) {
					stream.end({
						...defaultFields,
						role: "assistant",
						content: [{ type: "text", text: response }],
						stopReason: "aborted",
						errorMessage: "Request aborted",
						timestamp: Date.now(),
					} as AssistantMessage);
					return;
				}

				stream.push({
					type: "text_end",
					contentIndex: 0,
					content: response,
					partial: partialMessage,
				});
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [{ type: "text", text: response }],
					stopReason: "stop",
					timestamp: Date.now(),
				} as AssistantMessage);
			} catch (error) {
				stream.end({
					...defaultFields,
					role: "assistant",
					content: [],
					stopReason: "error",
					errorMessage: error instanceof Error ? error.message : String(error),
					timestamp: Date.now(),
				} as AssistantMessage);
			}
		})();

		return stream;
	};
}

export async function hybridStreamFn(model: Model<Api>, context: Context, options?: SimpleStreamOptions) {
	if (model.provider === "browser") {
		return normalizeToolCallStream(await createBrowserStreamFn()(model, context, options), context);
	}

	const apiKey = options?.apiKey ?? await getProviderApiKey(model.provider);
	let streamOptions: SimpleStreamOptions | undefined = apiKey ? { ...options, apiKey } : options;
	if (isNotOrganicProvider(model.provider)) {
		streamOptions = {
			...streamOptions,
			headers: {
				...streamOptions?.headers,
				"x-keating-provider": NOTORGANIC_PROVIDER_ID,
				"x-keating-feature": NOTORGANIC_FEATURE,
				"idempotency-key": `keating_${crypto.randomUUID()}`,
			},
		};
	}

	if (shouldProxyModel(model)) {
		const proxiedModel = {
			...model,
			baseUrl: chatProxyBaseUrl(),
		};
		const proxiedOptions: SimpleStreamOptions = {
			...streamOptions,
			headers: {
				...streamOptions?.headers,
				"x-target-url": proxyTargetHeader(model.baseUrl),
			},
		};
		if (import.meta.env.DEV) {
			const hasApiKey = !!proxiedOptions.apiKey;
			console.log(`[keating:stream] proxy ${model.provider} -> ${model.baseUrl} (apiKey=${hasApiKey})`);
		}
		const mergedOptions = withProviderWebSearch(proxiedOptions, proxiedModel, !!apiKey);
		return normalizeToolCallStream(
			streamWithApiRetry(proxiedModel, context, mergedOptions, (nextOptions) => streamSimple(proxiedModel, context, nextOptions)),
			context,
		);
	}

	const mergedOptions = withProviderWebSearch(streamOptions, model, !!apiKey);
	return normalizeToolCallStream(
		streamWithApiRetry(model, context, mergedOptions, (nextOptions) => streamSimple(model, context, nextOptions)),
		context,
	);
}

