        Type <code>{phrase}</code>
        <input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} />
      </label>
      <button
        className="danger"
        disabled={confirmation !== phrase}
        onClick={() =>
          void operation.run(
            () =>
              portalApi.requestDeletion(scope, {
                confirmation,
                idempotencyKey: crypto.randomUUID(),
                reason: `User confirmed ${scope} deletion in portal`,
              }),
            `${scope === "provider" ? "Provider data" : "Managed PDS account"} deletion requested.`,
          )
        }
      >
        Delete {scope === "provider" ? "provider data" : "managed PDS"}
      </button>
    </div>
  );
}

function AdminTools() {
  const [did, setDid] = useState("");
  const [status, setStatus] = useState<AccountStatus | null>(null);
  const [versions, setVersions] = useState<VersionView[]>([]);
  const [versionKind, setVersionKind] = useState<"routes" | "rates">("routes");
  const [audits, setAudits] = useState<AuditView[]>([]);
  const operation = useOperation();

  return (
    <div className="grid">
      <Panel eyebrow="Operations" title="Account and wallet status">
        <label>DID<input value={did} onChange={(event) => setDid(event.target.value)} placeholder="did:plc:…" /></label>
        <button onClick={() => void operation.run(async () => setStatus(await portalApi.adminStatus(did)), "Status refreshed.")}>
          Load status
        </button>
        {status && <pre>{JSON.stringify(status, null, 2)}</pre>}
      </Panel>
      <Panel eyebrow="Routing control plane" title="Immutable versions">
        <div className="button-row">
          {(["routes", "rates"] as const).map((kind) => (
            <button
              key={kind}
              onClick={() =>
                void operation.run(async () => {
                  setVersionKind(kind);
                  setVersions(await portalApi.adminVersions(kind));
                }, `${kind} loaded.`)
              }
            >
              Load {kind}
            </button>
          ))}
        </div>
        <ul className="version-list">
          {versions.map((version) => (
            <li key={version._id}>
              <strong>{version.version}</strong>
              {version.status === "draft" ? (
                <button
                  onClick={() =>
                    void operation.run(
                      () =>
                        portalApi.publishVersion(
                          versionKind,
                          version.version,
                          "Published from provider portal",
                        ),
                      `${version.version} published.`,
                    )
                  }
                >
                  Publish
                </button>
              ) : (
                <span>{version.status}</span>
              )}
            </li>
          ))}
        </ul>
      </Panel>
      <Panel eyebrow="Compliance" title="Admin audit">
        <button onClick={() => void operation.run(async () => setAudits(await portalApi.adminAudit()), "Audit refreshed.")}>Refresh audit</button>
        <ul className="audit-list">
          {audits.map((event) => <li key={event._id}><strong>{event.action}</strong><span>{event.target}</span><small>{event.reason}</small></li>)}
        </ul>
      </Panel>
      <p className="status-line">{operation.message}</p>
    </div>
  );
}

export function App() {
  const [view, setView] = useState<View>("account");
  return (
    <main>
      <header>
        <div><p className="eyebrow">Not Organic</p><h1>Provider control room</h1></div>
        <nav aria-label="Portal sections">
          <button aria-pressed={view === "account"} onClick={() => setView("account")}>My account</button>
          <button aria-pressed={view === "admin"} onClick={() => setView("admin")}>Admin</button>
        </nav>
      </header>
      <p className="lede">One DID across Twyne, Keating, and Interleave. Your inference wallet and managed PDS remain separate, legible systems.</p>
      {view === "account" ? <AccountTools /> : <AdminTools />}
    </main>
  );
}

