import { createError, defineEventHandler, getHeader, getHeaders, getRequestURL, proxyRequest } from "h3";
import { getDioGatewayBaseUrl, isAllowedDioOpenAiProxyRequest, isDioEnabled } from "../../../../src/dio-provider/server";
import {
	createNotOrganicServerClient,
	getNotOrganicServerConfig,
	isNotOrganicHostedEnabled,
	NotOrganicOperationalError,
} from "../../../../src/notorganic-provider/server";
import {
	NOTORGANIC_FEATURE,
	NOTORGANIC_PROVIDER_ID,
} from "../../../../src/notorganic-provider";

export default defineEventHandler(async (event) => {
	const reqUrl = getRequestURL(event);
	const proxyPath = reqUrl.pathname.replace(/^\/api\/dio\/openai\/?/, "") + reqUrl.search;
	if (!isAllowedDioOpenAiProxyRequest(event.method, proxyPath)) {
		throw createError({ statusCode: 404, statusMessage: "Not found" });
	}
	const requestedProvider = getHeader(event, "x-keating-provider");
	const isHostedRequest = requestedProvider === NOTORGANIC_PROVIDER_ID;
	if (isHostedRequest) {
		try {
			const config = getNotOrganicServerConfig();
			if (!config.enabled) {
				throw createError({ statusCode: 404, statusMessage: "Not found" });
			}
			const client = await createNotOrganicServerClient(event, NOTORGANIC_FEATURE, config);
			const targetPath = `/${proxyPath}`;
			return await client.request(targetPath, {
				method: event.method,
				body: event.method === "GET" || event.method === "HEAD" ? undefined : event.req.body,
				headers: {
					...(getHeader(event, "content-type") ? { "content-type": getHeader(event, "content-type")! } : {}),
					...(getHeader(event, "accept") ? { accept: getHeader(event, "accept")! } : {}),
				},
				idempotencyKey: getHeader(event, "idempotency-key") ?? undefined,
				maxCostMicrousd:
					event.method === "POST" && proxyPath.split("?")[0] === "v1/chat/completions"
						? config.maxCostMicrousd
						: undefined,
			});
		} catch (error) {
			if (error instanceof NotOrganicOperationalError) {
				throw createError({
					statusCode: error.statusCode,
					statusMessage: error.message,
					data: { code: error.code },
				});
			}
			throw error;
		}
	}

	if (!isDioEnabled()) {
		throw createError({ statusCode: 404, statusMessage: "Not found" });
	}
	if (isNotOrganicHostedEnabled() && process.env.DIO_LEGACY_COMPATIBILITY === "false") {
		throw createError({ statusCode: 410, statusMessage: "Legacy Dio proxy compatibility has ended" });
	}
	const targetUrl = `${getDioGatewayBaseUrl()}/${proxyPath}`;

	const forbiddenHeaders = [
		"x-stainless-os",
		"x-stainless-lang",
		"x-stainless-package-version",
		"x-stainless-runtime",
		"x-stainless-runtime-version",
		"x-stainless-arch",
		"x-stainless-os-version",
		"origin",
		"host",
		"referer",
		"x-target-url",
	];

	const headers: Record<string, string> = { ...getHeaders(event) };
	for (const forbidden of forbiddenHeaders) {
		delete headers[forbidden];
	}

	return proxyRequest(event, targetUrl, { headers });
});

