import { createError, defineEventHandler, getHeader, getRequestURL } from "h3";
import { NOTORGANIC_FEATURE } from "../../../../src/notorganic-provider";
import {
	createNotOrganicServerClient,
	getNotOrganicServerConfig,
	NotOrganicOperationalError,
} from "../../../../src/notorganic-provider/server";

const ALLOWED_ROUTES = new Set([
	"v1/chat/completions",
	"v1/responses",
	"v1/embeddings",
	"v1/images/generations",
	"v1/audio/speech",
	"v1/audio/transcriptions",
	"v1/audio/translations",
	"v1/models",
]);

export default defineEventHandler(async (event) => {
	const reqUrl = getRequestURL(event);
	const route = reqUrl.pathname
		.replace(/^\/api\/notorganic\/openai\/?/, "")
		.replace(/\/+$/, "");
	const allowedMethod =
		(event.method === "POST" && ALLOWED_ROUTES.has(route)) ||
		(event.method === "GET" && route === "v1/models");
	if (!allowedMethod) {
		throw createError({ statusCode: 404, statusMessage: "Not found" });
	}

	try {
		const config = getNotOrganicServerConfig();
		if (!config.enabled) {
			throw createError({ statusCode: 404, statusMessage: "Not found" });
		}
		const client = await createNotOrganicServerClient(event, NOTORGANIC_FEATURE, config);
		return await client.request(`/${route}${reqUrl.search}`, {
			method: event.method,
			body: event.method === "GET" ? undefined : event.req.body,
			headers: {
				...(getHeader(event, "content-type") ? { "content-type": getHeader(event, "content-type")! } : {}),
				...(getHeader(event, "accept") ? { accept: getHeader(event, "accept")! } : {}),
			},
			idempotencyKey: getHeader(event, "idempotency-key") ?? undefined,
			maxCostMicrousd: event.method === "POST" ? config.maxCostMicrousd : undefined,
		});
	} catch (error) {
		if (error instanceof NotOrganicOperationalError) {
			throw createError({
				statusCode: error.statusCode,
				statusMessage: error.message,
				data: { code: error.code },
			});
		}
		throw error;
	}
});
import {
	createError,
	defineEventHandler,
	getQuery,
	getRouterParam,
	readBody,
	type H3Event,
} from "h3";
import {
	createNotOrganicServerClient,
	getNotOrganicServerConfig,
	NotOrganicOperationalError,
} from "../../../../src/notorganic-provider/server";
import { isNotOrganicPackId } from "../../../../src/notorganic-provider/packs";

const RESOURCE_ROUTES = {
	account: { method: "GET", path: "/v1/account", feature: "keating:account" },
	wallet: { method: "GET", path: "/v1/wallet", feature: "keating:wallet" },
	usage: { method: "GET", path: "/v1/usage", feature: "keating:usage" },
	checkout: { method: "POST", path: "/v1/billing/checkout", feature: "keating:billing" },
} as const;

type ResourceName = keyof typeof RESOURCE_ROUTES;

function resourceName(event: H3Event): ResourceName | null {
	const value = getRouterParam(event, "resource");
	return typeof value === "string" && value in RESOURCE_ROUTES
		? value as ResourceName
		: null;
}

export default defineEventHandler(async (event) => {
	const resource = resourceName(event);
	if (!resource) throw createError({ statusCode: 404, statusMessage: "Not found" });
	const route = RESOURCE_ROUTES[resource];
	if (event.method !== route.method) {
		throw createError({ statusCode: 405, statusMessage: "Method not allowed" });
	}

	try {
		const client = await createNotOrganicServerClient(
			event,
			route.feature,
			getNotOrganicServerConfig(),
		);
		let path = route.path;
		let body: string | undefined;
		if (resource === "usage") {
			const query = getQuery(event);
			const parameters = new URLSearchParams();
			if (typeof query.after === "string") parameters.set("after", query.after);
			if (typeof query.limit === "string") parameters.set("limit", query.limit);
			if (parameters.size) path += `?${parameters}`;
		} else if (resource === "checkout") {
			const input = await readBody<{ product_id?: unknown; return_url?: unknown }>(event);
			if (typeof input?.return_url !== "string") {
				throw createError({ statusCode: 400, statusMessage: "return_url is required" });
			}
			if (typeof input?.product_id !== "string" || !isNotOrganicPackId(input.product_id)) {
				throw createError({ statusCode: 400, statusMessage: "A valid Keating product_id is required" });
			}
			const returnUrl = new URL(input.return_url);
			if (returnUrl.protocol !== "https:") {
				throw createError({ statusCode: 400, statusMessage: "return_url must use HTTPS" });
			}
			body = JSON.stringify({
				product_id: input.product_id,
				return_url: returnUrl.toString(),
			});
		}
		return await client.request(path, {
			method: route.method,
			body,
			headers: body ? { "content-type": "application/json" } : undefined,
		});
	} catch (error) {
		if (error instanceof NotOrganicOperationalError) {
			throw createError({
				statusCode: error.statusCode,
				statusMessage: error.message,
				data: { code: error.code },
			});
		}
		throw error;
	}
});

import type { Model } from "@earendil-works/pi-ai";

export const NOTORGANIC_PROVIDER_ID = "notorganic";
export const NOTORGANIC_MODEL_ALIAS = "balanced";
export const NOTORGANIC_FEATURE = "keating:web-chat";
export const NOTORGANIC_PROXY_BASE_PATH = "/api/notorganic/openai/v1";

export function notOrganicOpenAiBaseUrl(origin = currentOrigin()): string {
	return `${origin.replace(/\/+$/, "")}${NOTORGANIC_PROXY_BASE_PATH}`;
}

export const NOTORGANIC_DEFAULT_MODEL: Model<"openai-completions"> = {
	id: NOTORGANIC_MODEL_ALIAS,
	name: "Not Organic Balanced",
	api: "openai-completions",
	provider: NOTORGANIC_PROVIDER_ID,
	baseUrl: notOrganicOpenAiBaseUrl(),
	reasoning: true,
	input: ["text", "image"],
	cost: {
		input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
	},
	contextWindow: 256_000,
	maxTokens: 16_384,
};

export interface NotOrganicAccount {
	id: string;
	did?: string;
	[key: string]: unknown;
}

export interface NotOrganicWallet {
	balance_microusd?: number;
	[key: string]: unknown;
}

export interface NotOrganicUsage {
	object: string;
	data: unknown[];
	[key: string]: unknown;
}

export interface NotOrganicCheckout {
	url?: string;
	checkout_url?: string;
	[key: string]: unknown;
}

async function providerJson<T>(
	path: string,
	init?: RequestInit,
	fetcher: typeof fetch = fetch,
): Promise<T> {
	const response = await fetcher(`/api/notorganic/provider/${path}`, init);
	const body = await response.json().catch(() => ({}));
	if (!response.ok) {
		const message =
			typeof body?.error?.message === "string"
				? body.error.message
				: typeof body?.message === "string"
					? body.message
					: `Not Organic request failed (${response.status})`;
		throw new Error(message);
	}
	return body as T;
}

export function getNotOrganicAccount(fetcher?: typeof fetch): Promise<NotOrganicAccount> {
	return providerJson("account", undefined, fetcher);
}

export function getNotOrganicWallet(fetcher?: typeof fetch): Promise<NotOrganicWallet> {
	return providerJson("wallet", undefined, fetcher);
}

export function getNotOrganicUsage(
	options: { after?: string; limit?: number } = {},
	fetcher?: typeof fetch,
): Promise<NotOrganicUsage> {
	const query = new URLSearchParams();
	if (options.after) query.set("after", options.after);
	if (options.limit !== undefined) query.set("limit", String(options.limit));
	return providerJson(`usage${query.size ? `?${query}` : ""}`, undefined, fetcher);
}

export function createNotOrganicCheckout(
	productId: string,
	returnUrl: string,
	fetcher?: typeof fetch,
): Promise<NotOrganicCheckout> {
	return providerJson(
		"checkout",
		{
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify({ product_id: productId, return_url: returnUrl }),
		},
		fetcher,
	);
}

export function isNotOrganicProvider(provider: string): boolean {
	return provider === NOTORGANIC_PROVIDER_ID;
}

export function isNotOrganicFeatureEnabled(): boolean {
	let configured: string | undefined;
	if (typeof import.meta.env !== "undefined") {
		configured = import.meta.env.VITE_NOTORGANIC_ENABLED;
	} else if (typeof process !== "undefined") {
		configured = process.env.VITE_NOTORGANIC_ENABLED;
	}
	if (configured === "true") return true;
	if (configured === "false") return false;
	return false;
}

function currentOrigin(): string {
	return typeof globalThis.location?.origin === "string" && globalThis.location.origin
		? globalThis.location.origin
		: "http://localhost";
}
import type { H3Event } from "h3";
import {
