   165	): { code: string; edgeCount: number } | null {
   166		const flattened = flattenStudyPlanItems(items);
   167		const byId = new Map(flattened.map((item) => [item.id, item]));
   168		const nodeName = new Map(flattened.map((item, index) => [item.id, `step${index + 1}`]));
   169		const edges: Array<{ source: string; target: string }> = [];
   170	
   171		for (const item of flattened) {
   172			for (const dependencyId of item.dependsOn ?? []) {
   173				if (dependencyId !== item.id && byId.has(dependencyId)) {
   174					edges.push({ source: dependencyId, target: item.id });
   175				}
   176			}
   177		}
   178		if (edges.length === 0) return null;
   179	
   180		const visibleIds = new Set(edges.flatMap((edge) => [edge.source, edge.target]));
